
BEGIN;
--
-- Create model ActivationToken
--
CREATE TABLE "main_activationtoken" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "token" varchar(100) NOT NULL UNIQUE, "created_at" timestamp with time zone NOT NULL, "user_id" integer NOT NULL UNIQUE);
--
-- Create model AdresseUser
--
CREATE TABLE "main_adresseuser" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "numero" varchar(10) NOT NULL, "type_voie" varchar(100) NOT NULL, "nom_rue" varchar(100) NOT NULL, "complement" varchar(100) NULL, "code_postal" integer NOT NULL, "ville" varchar(100) NOT NULL, "pays" varchar(100) NOT NULL, "telephone" varchar(10) NULL, "email" varchar(100) NULL, "photo" varchar(100) NULL, "user_id" integer NOT NULL UNIQUE);
--
-- Create model ChoixRole
--
CREATE TABLE "main_choixrole" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "role" varchar NOT NULL, "user_id" integer NOT NULL UNIQUE);
--
