--
CREATE TABLE "main_credituser" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "credit" numeric(10, 2) NOT NULL, "user_id" integer NOT NULL UNIQUE);
