--
CREATE TABLE "main_preference" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "exigences_particulieres" varchar(50) NOT NULL, "exigences_personnelles" text NULL, "fumeur" varchar(50) NOT NULL, "animaux" varchar(50) NOT NULL, "user_preference_id" integer NULL UNIQUE);
--
-- Create model ReservationTrajet
--
CREATE TABLE "main_reservationtrajet" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "prix_par_passager" numeric(5, 2) NOT NULL, "places" integer NULL, "etat_reservation" varchar(20) NOT NULL, "reservation_rembourser" boolean NOT NULL, "etat_paiement" varchar(20) NOT NULL, "trajet_payer" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "passager_id" integer NULL);
