CREATE TABLE "main_tokenvalidation" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "token" varchar(128) NOT NULL UNIQUE, "action" varchar(20) NOT NULL, "created_at" timestamp with time zone NOT NULL, "user_id" integer NOT NULL UNIQUE);
--
-- Create model TrajetProposer
--
CREATE TABLE "main_trajetproposer" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "etat" varchar(15) NOT NULL, "trajet_rembourser" boolean NOT NULL, "ville_depart" varchar(50) NOT NULL, "ville_arrivee" varchar(50) NOT NULL, "date" date NOT NULL, "heure" time NOT NULL, "places" integer NOT NULL, "prix" numeric(5, 2) NOT NULL, "total_payer" numeric(5, 2) NULL, "temps_trajet" interval NOT NULL, "created_at" timestamp with time zone NULL, "chauffeur_id" integer NOT NULL);
